function UIFeelingFavorabilityRewardDetailsDialog:FillSelf()
    CfUtils.FillImage(self.IconHead, nil)
    CfUtils.FillText(self.Txtknow, localize("相识"))

    local lastY = 0
    local lastM = 0
    local lastD = 0
    if self._catDojo.unlockPhoneDay then
        local t = CfUtils.Split(self._catDojo.unlockPhoneDay, "-")
        if t then
            lastY = checkNumber(t[1])
            lastM = checkNumber(t[2])
            lastD = checkNumber(t[3])
        end
    end
    local beginTime = checkNumber(os.time({day=lastD, month=lastM, year=lastY, hour=0, minute=0, second=0}))
    local curTime = checkNumber(os.time())
    local disDay = math.floor((curTime - beginTime) / (3600 * 24)) + 1
    CfUtils.FillText(self.Txtday, localize("<color=#a50000><size=40>_num_</size></color>天", {_num_ = disDay}))

    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(self._catId)
    CfUtils.FillImage(self.IconHead, CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId))
    
    SetButtonAction(self.bgBlack, function()
        UIModule.CloseDialog(self.controller)
    end)

    self.LoopScrollView:InitGridView(#self._allInfo, Bind(self, self.OnGetCellByIndex))
end

function UIFeelingFavorabilityRewardDetailsDialog:OnGetCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._allInfo[index + 1]
    local cell = listView:NewListViewItem("itemcel")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingFavorabilityRewardDetailsCellNode)
    if scr then
        scr:Refresh(data)
    end

    return cell
end

